/* === varexpand.c === */

static int is_varchar(int c) { return isalnum(c) || c == '_'; }

int varexpand(const char *input, char **out, char **undefined_var) {
  size_t cap = 256, len = 0;
  char *buf = malloc(cap);
  const char *p = input;

  *out = NULL;
  if (undefined_var)
    *undefined_var = NULL;

#define APPEND(ch)                                                             \
  do {                                                                         \
    if (len + 1 >= cap) {                                                      \
      cap *= 2;                                                                \
      char *tmp_ = realloc(buf, cap);                                          \
      if (!tmp_) {                                                             \
        free(buf);                                                             \
        return -1;                                                             \
      }                                                                        \
      buf = tmp_;                                                              \
    }                                                                          \
    buf[len++] = (ch);                                                         \
  } while (0)

  while (*p) {
    if (*p == '$') {
      p++;
      if (*p == '{') {
        /* ${VAR} form */
        p++;
        const char *start = p;
        while (*p && *p != '}')
          p++;
        if (*p != '}') {
          /* Malformed, treat as literal */
          APPEND('$');
          APPEND('{');
          p = start;
          continue;
        }
        size_t namelen = (size_t)(p - start);
        char *name = malloc(namelen + 1);
        memcpy(name, start, namelen);
        name[namelen] = '\0';
        p++; /* skip '}' */

        const char *val = getenv(name);
        if (!val) {
          if (undefined_var)
            *undefined_var = name;
          else
            free(name);
          free(buf);
          return -1;
        }
        free(name);
        while (*val)
          APPEND(*val++);
      } else if (is_varchar(*p)) {
        /* $VAR form */
        const char *start = p;
        while (*p && is_varchar(*p))
          p++;
        size_t namelen = (size_t)(p - start);
        char *name = malloc(namelen + 1);
        memcpy(name, start, namelen);
        name[namelen] = '\0';

        const char *val = getenv(name);
        if (!val) {
          if (undefined_var)
            *undefined_var = name;
          else
            free(name);
          free(buf);
          return -1;
        }
        free(name);
        while (*val)
          APPEND(*val++);
      } else {
        /* Lone $, treat as literal */
        APPEND('$');
      }
    } else {
      APPEND(*p);
      p++;
    }
  }

  buf[len] = '\0';
  *out = buf;
  return 0;

#undef APPEND
}

/* === envfile.c === */

int envfile_load(const char *path) {
  FILE *f = fopen(path, "r");
  if (!f) {
    fprintf(stderr, "error: cannot open env file '%s'\n", path);
    return -1;
  }

  char line[4096];
  while (fgets(line, sizeof(line), f)) {
    /* Strip trailing newline */
    size_t len = strlen(line);
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
      line[--len] = '\0';

    /* Skip blank lines and comments */
    const char *p = line;
    while (*p && isspace((unsigned char)*p))
      p++;
    if (*p == '\0' || *p == '#')
      continue;

    /* Find '=' separator */
    char *eq = strchr(line, '=');
    if (!eq)
      continue;

    *eq = '\0';
    const char *value = eq + 1;

    /* Trim leading and trailing whitespace from key */
    const char *key = line;
    while (*key && isspace((unsigned char)*key))
      key++;
    char *kend = eq - 1;
    while (kend >= key && isspace((unsigned char)*kend))
      *kend-- = '\0';

      /* Set env var only if not already set (user environment takes priority)
       */
#ifdef _WIN32
    {
      const char *existing = getenv(key);
      if (!existing) {
        _putenv_s(key, value);
      }
    }
#else
    setenv(key, value, 0);
#endif
  }

  fclose(f);
  return 0;
}

