  if (!created) {
    DeleteFileA(scriptfile);
    CloseHandle(stdout_rd);
    CloseHandle(stdout_wr);
    CloseHandle(stderr_rd);
    CloseHandle(stderr_wr);
    return -1;
  }

  /* Close write ends so reads can detect EOF */
  CloseHandle(stdout_wr);
  CloseHandle(stderr_wr);

  *out_stdout = read_handle(stdout_rd);
