/* === progress.c === */

#ifdef _WIN32
/* strdup is available as _strdup on MSVC */
#ifndef strdup
#define strdup _strdup
#endif
#else
#endif

#define BAR_WIDTH 40

void progress_init(ProgressCtx *ctx, int total, int num_workers,
                   TestCaseResult *results) {
  ctx->total = total;
  ctx->num_workers = num_workers;
  ctx->results = results;
  ctx->completed = 0;
  ctx->failed = 0;
  ctx->done = 0;

  ctx->worker_names = calloc((size_t)num_workers, sizeof(char *));
  for (int i = 0; i < num_workers; i++) {
    ctx->worker_names[i] = strdup("(idle)");
  }

#ifdef _WIN32
  InitializeCriticalSection(&ctx->mutex);
  InitializeCriticalSection(&ctx->worker_mutex);
#else
  pthread_mutex_init(&ctx->mutex, NULL);
  pthread_mutex_init(&ctx->worker_mutex, NULL);
#endif
}

void progress_complete(ProgressCtx *ctx, int passed) {
#ifdef _WIN32
  EnterCriticalSection(&ctx->mutex);
#else
  pthread_mutex_lock(&ctx->mutex);
#endif
  ctx->completed++;
  if (!passed)
    ctx->failed++;
#ifdef _WIN32
  LeaveCriticalSection(&ctx->mutex);
#else
  pthread_mutex_unlock(&ctx->mutex);
#endif
}

void progress_set_worker(ProgressCtx *ctx, int worker_id, const char *name) {
  if (worker_id < 0 || worker_id >= ctx->num_workers)
    return;
#ifdef _WIN32
  EnterCriticalSection(&ctx->worker_mutex);
#else
  pthread_mutex_lock(&ctx->worker_mutex);
#endif
  free(ctx->worker_names[worker_id]);
  ctx->worker_names[worker_id] = strdup(name ? name : "(idle)");
#ifdef _WIN32
  LeaveCriticalSection(&ctx->worker_mutex);
#else
  pthread_mutex_unlock(&ctx->worker_mutex);
#endif
}

static void render_progress(ProgressCtx *ctx) {
  int total = ctx->total;
  int num_workers = ctx->num_workers;

#ifdef _WIN32
  EnterCriticalSection(&ctx->mutex);
#else
  pthread_mutex_lock(&ctx->mutex);
#endif
  int completed = ctx->completed;
  int failed = ctx->failed;
#ifdef _WIN32
  LeaveCriticalSection(&ctx->mutex);
#else
  pthread_mutex_unlock(&ctx->mutex);
#endif

  /* Build the progress bar proportionally */
  char bar[BAR_WIDTH + 1];
  int passed = completed - failed;
  /* Proportional bar: passed=#, failed=x, pending=. */
  int pass_chars = (total > 0) ? (passed * BAR_WIDTH / total) : 0;
  int fail_chars = (total > 0) ? (failed * BAR_WIDTH / total) : 0;
  /* Ensure at least 1 char for failed if there are failures */
  if (failed > 0 && fail_chars == 0)
    fail_chars = 1;
  /* Adjust pass_chars if total exceeds bar width */
  if (pass_chars + fail_chars > BAR_WIDTH)
    pass_chars = BAR_WIDTH - fail_chars;
  int pending_chars = BAR_WIDTH - pass_chars - fail_chars;

  int pos = 0;
  for (int i = 0; i < pass_chars; i++)
    bar[pos++] = '#';
  for (int i = 0; i < fail_chars; i++)
    bar[pos++] = 'x';
  for (int i = 0; i < pending_chars; i++)
    bar[pos++] = '.';
  bar[BAR_WIDTH] = '\0';

  /* Move cursor up and clear lines (num_workers + 2 lines: bar + progress +
   * workers) */
  static int first_render = 1;
  if (!first_render) {
    /* Move cursor up by (2 + num_workers) lines */
    fprintf(stderr, "\033[%dA", 2 + num_workers);
  }
  first_render = 0;

  /* Render bar */
  fprintf(stderr, "\033[K[%s]\n", bar);
  fprintf(stderr, "\033[KProgress: %d/%d completed, %d failed\n", completed,
          total, failed);

  /* Render worker status */
#ifdef _WIN32
  EnterCriticalSection(&ctx->worker_mutex);
#else
  pthread_mutex_lock(&ctx->worker_mutex);
#endif
  for (int i = 0; i < num_workers; i++) {
    fprintf(stderr, "\033[KWorker %d: %s\n", i + 1, ctx->worker_names[i]);
  }
#ifdef _WIN32
  LeaveCriticalSection(&ctx->worker_mutex);
#else
  pthread_mutex_unlock(&ctx->worker_mutex);
#endif

  fflush(stderr);
}

void *progress_thread_func(void *arg) {
  ProgressCtx *ctx = (ProgressCtx *)arg;

  while (!ctx->done) {
    render_progress(ctx);
#ifdef _WIN32
    Sleep(100); /* 100ms */
#else
    usleep(100000); /* 100ms */
#endif
  }

  /* Final render */
  render_progress(ctx);

  /* Clear progress lines after completion */
  int lines = 2 + ctx->num_workers;
  fprintf(stderr, "\033[%dA", lines);
  for (int i = 0; i < lines; i++) {
    fprintf(stderr, "\033[K\n");
  }
  fprintf(stderr, "\033[%dA", lines);
  fflush(stderr);

  return NULL;
}

void progress_cleanup(ProgressCtx *ctx) {
  for (int i = 0; i < ctx->num_workers; i++) {
    free(ctx->worker_names[i]);
  }
  free(ctx->worker_names);
#ifdef _WIN32
  DeleteCriticalSection(&ctx->mutex);
  DeleteCriticalSection(&ctx->worker_mutex);
#else
  pthread_mutex_destroy(&ctx->mutex);
  pthread_mutex_destroy(&ctx->worker_mutex);
#endif
}

/* === runner.c === */

static TestCaseResult make_result(TestResult r, const char *msg,
                                  const char *case_name) {
  TestCaseResult res;
  res.result = r;
  res.message = msg ? strdup(msg) : NULL;
  res.case_name = case_name ? strdup(case_name) : NULL;
  return res;
}

TestCaseResult run_test_case(const TestCase *tc, const char *workdir,
                             int verbose) {
  TestStep *step = tc->steps;

  while (step) {
    if (step->type == STEP_AT_DATA) {
      /* Create file in workdir */
      char filepath[4096];
      snprintf(filepath, sizeof(filepath), "%s/%s", workdir,
               step->u.data.filename);

      /* Variable expand on content */
      char *expanded = NULL;
      char *undef_var = NULL;
      if (varexpand(step->u.data.content, &expanded, &undef_var) < 0) {
        char msg[512];
        snprintf(msg, sizeof(msg), "undefined variable: %s (in AT_DATA)",
                 undef_var ? undef_var : "?");
        free(undef_var);
        return make_result(RESULT_VAREXPAND_ERROR, msg, tc->description);
      }

      /* Create parent directories if needed */
      char *last_slash = strrchr(filepath, '/');
      if (last_slash) {
        *last_slash = '\0';
        os_mkdir_p(filepath);
        *last_slash = '/';
      }

      if (os_write_file(filepath, expanded, strlen(expanded)) < 0) {
        free(expanded);
        char msg[512];
        snprintf(msg, sizeof(msg), "failed to write file: %s", filepath);
        return make_result(RESULT_FAIL, msg, tc->description);
      }
      free(expanded);

    } else if (step->type == STEP_AT_CHECK) {
      /* Variable expand on command */
      char *expanded_cmd = NULL;
      char *undef_var = NULL;
      if (varexpand(step->u.check.command, &expanded_cmd, &undef_var) < 0) {
        char msg[512];
        snprintf(msg, sizeof(msg), "undefined variable: %s (in AT_CHECK)",
                 undef_var ? undef_var : "?");
        free(undef_var);
        return make_result(RESULT_VAREXPAND_ERROR, msg, tc->description);
      }

      char *actual_stdout = NULL;
      char *actual_stderr = NULL;
      int actual_exit = -1;

      if (verbose) {
        fprintf(stderr, "  AT_CHECK: %s\n", expanded_cmd);
      }

      if (os_exec_capture(expanded_cmd, &actual_stdout, &actual_stderr,
                          &actual_exit, workdir) < 0) {
        free(expanded_cmd);
        return make_result(RESULT_FAIL, "failed to execute command",
                           tc->description);
      }
      free(expanded_cmd);

      /* Check exit code */
      if (actual_exit != step->u.check.exit_code) {
        char msg[1024];
        snprintf(msg, sizeof(msg),
                 "exit code mismatch: expected %d, got %d\n"
                 "--- command: %s\n"
                 "--- stdout: %s\n"
                 "--- stderr: %s",
                 step->u.check.exit_code, actual_exit, step->u.check.command,
                 actual_stdout ? actual_stdout : "",
                 actual_stderr ? actual_stderr : "");
        free(actual_stdout);
        free(actual_stderr);
        return make_result(RESULT_FAIL, msg, tc->description);
      }

      /* Check stdout */
      if (step->u.check.has_stdout || strlen(step->u.check.expect_stdout) > 0) {
        /* Variable expand on expected stdout */
        char *exp_stdout = NULL;
        if (varexpand(step->u.check.expect_stdout, &exp_stdout, NULL) < 0) {
          free(actual_stdout);
          free(actual_stderr);
          return make_result(RESULT_VAREXPAND_ERROR,
                             "variable expansion error in expected stdout",
                             tc->description);
        }
        if (strcmp(actual_stdout ? actual_stdout : "", exp_stdout) != 0) {
          char msg[2048];
          snprintf(msg, sizeof(msg),
                   "stdout mismatch:\n"
                   "--- expected ---\n%s\n"
                   "--- actual ---\n%s",
                   exp_stdout, actual_stdout ? actual_stdout : "");
          free(exp_stdout);
          free(actual_stdout);
          free(actual_stderr);
          return make_result(RESULT_FAIL, msg, tc->description);
        }
        free(exp_stdout);
      }

      /* Check stderr */
      if (step->u.check.has_stderr || strlen(step->u.check.expect_stderr) > 0) {
        char *exp_stderr = NULL;
        if (varexpand(step->u.check.expect_stderr, &exp_stderr, NULL) < 0) {
          free(actual_stdout);
          free(actual_stderr);
          return make_result(RESULT_VAREXPAND_ERROR,
                             "variable expansion error in expected stderr",
                             tc->description);
        }
        if (strcmp(actual_stderr ? actual_stderr : "", exp_stderr) != 0) {
          char msg[2048];
          snprintf(msg, sizeof(msg),
                   "stderr mismatch:\n"
                   "--- expected ---\n%s\n"
                   "--- actual ---\n%s",
                   exp_stderr, actual_stderr ? actual_stderr : "");
          free(exp_stderr);
          free(actual_stdout);
          free(actual_stderr);
          return make_result(RESULT_FAIL, msg, tc->description);
        }
        free(exp_stderr);
      }

      free(actual_stdout);
      free(actual_stderr);
    }

    step = step->next;
  }

  return make_result(RESULT_PASS, NULL, tc->description);
}

